"""Gate GT (change-request workflow) and TS1 (testspec workflow): test specs generated by tsagent (SOLUTION sections 3, 4).

GT runs right after G4, starts a ``testspec`` child run and returns; G5 and the coding branch never wait for the child run.
TS1 reads a design-KG snapshot, chooses the scope, projects it to tdd-kg/v1, calls tsagent and writes the three documents (Draft, for reading).
"""
from __future__ import annotations

import os
import subprocess
import sys
from datetime import UTC, datetime

from ...errors import TddAgentError
from ...orchestrator.context import GateContext
from ...orchestrator.model import GateOutcome
from ..common import upstream
from . import context as ctxdoc
from . import kgclient, runner
from .codes import norm_feature
from .mapping import fingerprint, load_mapping
from .project import build_package
from .scope import cr_scopes, tdd_scope

FLOW = "testspec"


# ------------------------------------------------------------------ starting the child run
def launch_detached(cfg, child_id: str) -> int:
    """Run ``tdd-agent run advance <child>`` in its own session: the current command ends, the child run keeps going."""
    logs = cfg.work_dir / "logs"
    logs.mkdir(parents=True, exist_ok=True)
    log = (logs / f"testspec-{child_id}.log").open("ab")
    cmd = [sys.executable, "-m", "tdd_agent.cli", "-C", str(cfg.base_dir), "run", "advance", child_id]
    proc = subprocess.Popen(cmd, stdout=log, stderr=subprocess.STDOUT, stdin=subprocess.DEVNULL, start_new_session=True,
                            close_fds=True, env=os.environ.copy())
    log.close()
    return proc.pid


LAUNCH = launch_detached  # replaced in tests (run in process, or only record the call)


def children_of(operational, parent_id: str) -> list:
    """``testspec`` child runs of a run, newest first."""
    runs = [r for r in operational.list_runs(flow=FLOW, limit=100000) if r.parent_run_id == parent_id]
    return sorted(runs, key=lambda r: (r.created_at, r.run_id), reverse=True)


# ------------------------------------------------------------------ input hashes
def gt_extra_inputs(ctx: GateContext) -> dict:
    ts = ctx.config.section("testspec")
    return {"testspec": {k: ts[k] for k in ("enabled", "llm", "specs_dir")}, "mapping": fingerprint(),
            "context": ctxdoc.fingerprint(ctx.config)}


def ts1_extra_inputs(ctx: GateContext) -> dict:
    return {"mapping": fingerprint(), "context": ctxdoc.fingerprint(ctx.config, ctx.request.get("params"))}


# ------------------------------------------------------------------ GT
def _find(node, key):
    if isinstance(node, dict):
        if key in node and isinstance(node[key], dict):
            return node[key]
        for v in node.values():
            r = _find(v, key)
            if r is not None:
                return r
    elif isinstance(node, list):
        for v in node:
            r = _find(v, key)
            if r is not None:
                return r
    return None


def _cr_acceptance(g0: dict) -> list[dict]:
    """CR acceptance criteria from the G0 output: code + GIVEN/WHEN/THEN text when the CR has it (``acceptance_text``)."""
    texts = dict(_find(g0, "acceptance_text") or {})
    return [{"id": a, "text": texts.get(a) or None} for a in (g0.get("cr") or {}).get("acceptance") or []]


def complete_cr_params(params: dict, graph: dict, default_tdd: str) -> dict:
    """Complete from the change-spec items (read over MCP): affected TDDs (``tdd_refs``), criteria only found on items, and the criterion
    text from an item's ``verification`` when the item has a single criterion and G0 has no text."""
    by_id = {e["id"]: e for e in graph.get("elements", [])}
    items = [by_id[x] for x in params.get("cs_elements") or [] if x in by_id]
    tdds = list(params.get("tdds") or [])
    acc = {a["id"]: dict(a) for a in params.get("acceptance") or []}
    for it in items:
        props = it.get("props") or {}
        for r in props.get("tdd_refs") or []:
            if r.get("document_id") and r["document_id"] not in tdds:
                tdds.append(r["document_id"])
        refs = list(props.get("cr_acceptance_refs") or [])
        for a in refs:
            acc.setdefault(a, {"id": a, "text": None})
            v = props.get("verification")
            if not acc[a]["text"] and len(refs) == 1 and v:
                acc[a]["text"] = v if isinstance(v, str) else "; ".join(map(str, v)) if isinstance(v, list) else str(v)
    cr_id = params.get("cr_id") or next(((it.get("props") or {}).get("cr_id") for it in items), None)
    return {**params, "tdds": tdds or [default_tdd], "acceptance": list(acc.values()), "cr_id": cr_id, "default_tdd": default_tdd}


def gt_gate(ctx: GateContext) -> GateOutcome:
    """Reads no KG: only hands the G4 snapshot id, the change-spec item ids and the CR criteria (G0 output) to the child run."""
    ts = ctx.config.section("testspec")
    if not ts["enabled"]:
        return GateOutcome.ok({"enabled": False})
    g0, g4 = upstream(ctx, "G0"), upstream(ctx, "G4")
    cs = list(g4.get("cs_elements") or [])
    request = {"mode": "cr", "params": {"parent_run_id": ctx.run_id, "cr_id": (g0.get("cr") or {}).get("id"), "snapshot": g4.get("snapshot"),
                                        "cs_elements": cs, "acceptance": _cr_acceptance(g0)}}
    previous = children_of(ctx.operational, ctx.run_id)
    try:
        pre = {"ok": True, **runner.preflight(ctx.config)}
    except TddAgentError as exc:
        pre = {"ok": False, "code": exc.code, "error": str(exc)}
    child = ctx.children.start(FLOW, request)
    out = {"enabled": True, "child_run_id": child, "snapshot": g4.get("snapshot"), "preflight": pre, "cs_elements": cs,
           "launched_at": datetime.now(UTC).isoformat(), "supersedes": previous[0].run_id if previous else None}
    if pre["ok"]:
        out.update(launched="detached", pid=LAUNCH(ctx.config, child))
    else:
        out.update(launched="inline", child_status=ctx.children.advance(child))   # stops at once with the configuration error
    return GateOutcome.ok(out)


# ------------------------------------------------------------------ TS1
def ts1_gate(ctx: GateContext) -> GateOutcome:
    """Read the design KG over MCP (never ``ctx.knowledge``), project it to tdd-kg/v1, call tsagent."""
    p = ctx.request.get("params") or {}
    cfg = ctx.config
    llm = runner.preflight(cfg)                 # LLM configuration error: stop before anything else
    bundle = ctxdoc.load(cfg, p)                # context_mode plan | solution: a missing or unreadable document stops the run here
    mapping = load_mapping()
    parent = p.get("parent_run_id") or ctx.run.parent_run_id
    default_tdd = cfg.get("project.tdd_id") or "TDD"
    if p.get("cs_elements"):
        if parent:
            latest = children_of(ctx.operational, parent)
            if latest and latest[0].run_id != ctx.run_id:
                return GateOutcome.ok({"superseded_by": latest[0].run_id})
        read = kgclient.read_graph(cfg, "cr", p, mapping)
        graph, info = read["graph"], read["info"]
        if p.get("snapshot_hash") and info["hash"] != p["snapshot_hash"]:
            raise TddAgentError(f"snapshot {info['id']} hash {info['hash']} != {p['snapshot_hash']}", code="TESTSPEC_SNAPSHOT_MISMATCH")
        p = complete_cr_params(p, graph, default_tdd)
        scopes = cr_scopes(graph, p, mapping)
        kind, cr = "slice", p.get("cr_id")
    else:
        if not p.get("tdd"):
            raise TddAgentError("manual test-spec run needs params.tdd (the TDD id)", code="TESTSPEC_PARAM:tdd")
        read = kgclient.read_graph(cfg, "tdd", p, mapping)
        graph, info = read["graph"], read["info"]
        scopes = [tdd_scope(graph, p["tdd"], mapping, members_ids=read["members"])]
        kind, cr = "full", None
    if bundle is not None and bundle.snapshot and bundle.snapshot != info["id"]:
        bundle.notes.append(f"the document was written on snapshot {bundle.snapshot}; this run reads {info['id']}")
    packages = []
    for s in scopes:
        feature = p.get("feature") if p.get("feature") and len(scopes) == 1 else norm_feature(s.tdd)
        pkg, rep = build_package(graph, s, mapping=mapping, feature=feature, cr=cr, kind=kind, generated_at=info["created_at"],
                                 source_hash=f"sha256:{info['hash']}", context=bundle)
        rep.update(tdd=s.tdd, unresolved_refs=s.unresolved_refs)
        if p.get("cs_elements"):
            rep["acceptance"] = sorted({n["code"] for n in pkg["nodes"] if n["class"] == "AcceptanceCriterion" and n["props"].get("derivation") == "cr"})
        packages.append((pkg, rep))
    origin = {"system": "tdd-agent", "project": str(cfg.base_dir), "run_id": ctx.run_id, "parent_run_id": parent, "cr_id": cr,
              "snapshot": info["id"], "snapshot_hash": info["hash"], "cs_elements": list(p.get("cs_elements") or []),
              "mapping_version": mapping["version"], "kg_source": cfg.section("testspec")["kg_mcp"] or "mcp:stdio"}
    if bundle is not None:
        origin["context"] = bundle.meta()
    summary = runner.run_packages(cfg, ctx.run_id, packages, origin)
    summary.update(snapshot=info["id"], mode="cr" if p.get("cs_elements") else "manual", llm=llm["llm"],
                   kg={"source": origin["kg_source"], "mcp_calls": read["calls"], "elements": len(graph["elements"]), "edges": len(graph["edges"])},
                   context_mode=bundle.mode if bundle else "none")
    if summary["blockers"]:
        return GateOutcome.blocked(*summary["blockers"], output=summary)
    return GateOutcome.ok(summary)
